// La reponse utile est dans .body (fullResponse). Un echec arrive ici sous
// forme d'item sans body plutot qu'en exception (neverError).
const rep = ($json && typeof $json === 'object' && $json.body) ? $json.body : {};
const scan = rep.scan ?? {};
const pipeline = rep.pipeline ?? {};
const offres = Array.isArray(rep.offres) ? rep.offres.slice(0, 15) : [];

// Une panne du scanner doit se distinguer d'une tournee qui n'a rien trouve :
// les deux rendent zero offre, mais l'une est un incident et l'autre un lundi calme.
const enPanne = Boolean(rep.error) || Number($json.statusCode) >= 400;
const motif = String(rep.error || (Number($json.statusCode) >= 400 ? 'HTTP ' + $json.statusCode : ''));
const gardees = Number(scan.offres_gardees ?? 0);
const enAttente = Number(pipeline.en_attente ?? 0);

// Les intitules viennent d'annuaires publics : ils sont echappes avant d'entrer
// dans le HTML du courriel.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let liste = '';
for (const o of offres) {
  liste += '<li><strong>' + esc(o.pertinence ?? '?') + '/100</strong> - ' + esc(o.entreprise || '?')
    + ' - <a href="' + esc(o.url) + '">' + esc(o.poste || '?') + '</a><br><small>'
    + esc(Array.isArray(o.raisons) ? o.raisons.join(' · ') : '') + '</small></li>';
}

const corpsHtml = enPanne
  ? '<h2>La tournee de decouverte a echoue</h2><p>' + esc(motif || 'raison inconnue')
    + '</p><p>Rien n a ete ajoute au pipeline.</p>'
  : '<h2>Decouverte ATS</h2><p><strong>' + gardees + '</strong> nouvelle(s) offre(s) ajoutee(s) au pipeline. '
    + '<strong>' + enAttente + '</strong> en attente de decision.</p>'
    + '<p><a href="n8n.exemple.internal/pipeline">Ouvrir le pipeline</a></p>'
    + (liste ? '<hr><h3>Les mieux classees</h3><ul>' + liste + '</ul>' : '')
    + '<hr><p><small>' + Number(scan.entreprises_scannees ?? 0) + ' entreprises balayees sur '
    + Number(scan.entreprises_disponibles ?? 0) + ' disponibles'
    + (scan.plafond_atteint === true ? ' (plafond atteint : remonter limiteEntreprises pour aller plus loin)' : '')
    + '. ' + Number(scan.annuaires_injoignables ?? 0) + ' annuaire(s) injoignable(s).</small></p>';

return [{
  json: {
    enPanne,
    motif,
    offresGardees: gardees,
    enAttente,
    entreprisesScannees: Number(scan.entreprises_scannees ?? 0),
    annuairesInjoignables: Number(scan.annuaires_injoignables ?? 0),
    sujet: enPanne
      ? '[ALERTE] Decouverte ATS en echec'
      : 'Decouverte ATS : ' + gardees + ' nouvelle(s), ' + enAttente + ' en attente',
    corpsHtml,
    // Rien a annoncer quand la tournee n'a rien ramene ET que rien n'attend :
    // un courriel quotidien qui dit zero finit par ne plus etre lu.
    aAnnoncer: enPanne || gardees > 0 || enAttente > 0,
  },
}];
